-- Data invariants for the demo database: every row should print 0 except the org list.
-- npm run check:data   (after npm run seed, and before recording the demo)

\pset format unaligned
\pset tuples_only on
select 'I1 invoiced procedure not on a live invoice', count(*) from charted_procedures cp where cp.status='invoiced' and cp.deleted_at is null and not exists (select 1 from invoice_lines l join invoices i on i.id=l.invoice_id where l.charted_procedure_id=cp.id and i.status<>'void');
select 'I2 procedure on live invoice but not invoiced', count(*) from invoice_lines l join invoices i on i.id=l.invoice_id join charted_procedures cp on cp.id=l.charted_procedure_id where i.status<>'void' and cp.status<>'invoiced';
select 'I3 procedure on two live invoices', count(*) from (select l.charted_procedure_id from invoice_lines l join invoices i on i.id=l.invoice_id where i.status<>'void' group by 1 having count(*)>1) x;
select 'I4 invoice totals != sum of lines', count(*) from invoices i where (select coalesce(sum(line_total),0) from invoice_lines where invoice_id=i.id)<>i.total or (select coalesce(sum(unit_price*quantity),0) from invoice_lines where invoice_id=i.id)<>i.subtotal or (select coalesce(sum(tax_amount),0) from invoice_lines where invoice_id=i.id)<>i.tax_total;
select 'I5 line unit+tax != total', count(*) from invoice_lines where unit_price*quantity+tax_amount<>line_total;
select 'I6 invoice overpaid (live allocations > total+adj)', count(*) from invoices i where i.status<>'void' and (select coalesce(sum(a.amount),0) from payment_allocations a where a.invoice_id=i.id and not exists (select 1 from payment_reversals r where r.payment_id=a.payment_id)) > i.total+(select coalesce(sum(amount),0) from adjustments where invoice_id=i.id);
select 'I7 payment over-allocated', count(*) from payments p where (select coalesce(sum(a.amount),0) from payment_allocations a join invoices i on i.id=a.invoice_id where a.payment_id=p.id and i.status<>'void')>p.amount;
select 'I8 allocation to other patient invoice', count(*) from payment_allocations a join payments p on p.id=a.payment_id join invoices i on i.id=a.invoice_id where p.patient_id<>i.patient_id;
select 'I9 negative outstanding after adjustments', count(*) from invoices i where i.total+(select coalesce(sum(amount),0) from adjustments where invoice_id=i.id)<0;
select 'I10 completed proc without completed_at', count(*) from charted_procedures where status in ('completed','invoiced') and completed_at is null and deleted_at is null;
select 'I11 invoiced without invoiced_at / completed with invoiced_at', count(*) from charted_procedures where (status='invoiced' and invoiced_at is null) or (status<>'invoiced' and invoiced_at is not null);
select 'I12 counter behind max invoice number', count(*) from invoice_number_counters c where c.last_value < (select coalesce(max(split_part(invoice_number,'-',3)::int),0) from invoices i where i.organization_id=c.organization_id and split_part(invoice_number,'-',2)::int=c.year);
select 'I13 overlapping live appointments same provider', count(*) from appointments a join appointments b on a.provider_id=b.provider_id and a.id<b.id and a.starts_at<b.ends_at and b.starts_at<a.ends_at where a.status not in ('cancelled','no_show') and b.status not in ('cancelled','no_show') and a.deleted_at is null and b.deleted_at is null;
select 'I14 overlapping live appointments same chair', count(*) from appointments a join appointments b on a.operatory_id=b.operatory_id and a.id<b.id and a.starts_at<b.ends_at and b.starts_at<a.ends_at where a.status not in ('cancelled','no_show') and b.status not in ('cancelled','no_show') and a.deleted_at is null and b.deleted_at is null;
select 'I15 appointment outside provider hours', count(*) from appointments a where a.status not in ('cancelled') and a.deleted_at is null and not exists (select 1 from provider_schedules s where s.provider_id=a.provider_id and s.day_of_week=extract(dow from a.starts_at at time zone 'Asia/Kolkata') and (a.starts_at at time zone 'Asia/Kolkata')::time>=s.start_time and (a.ends_at at time zone 'Asia/Kolkata')::time<=s.end_time);
select 'I16 future appt with past-only status', count(*) from appointments where starts_at>now() and status in ('completed','arrived','seated','no_show');
select 'I17 past appt still scheduled/confirmed (>1 day)', count(*) from appointments where ends_at<now()-interval '1 day' and status in ('scheduled','confirmed');
select 'I18 accepted plan with no accepted_at, or presented missing', count(*) from treatment_plans where (status in ('accepted','completed') and accepted_at is null) or (status<>'draft' and presented_at is null);
select 'I19 completed plan with open items', count(*) from treatment_plans t where t.status='completed' and exists (select 1 from treatment_plan_items it join charted_procedures cp on cp.id=it.charted_procedure_id where it.deleted_at is null and cp.status not in ('completed','invoiced','cancelled') and it.treatment_plan_phase_id in (select id from treatment_plan_phases where treatment_plan_id=t.id));
select 'I20 accepted plan should have completed (all done)', count(*) from treatment_plans t where t.status='accepted' and not exists (select 1 from treatment_plan_items it join charted_procedures cp on cp.id=it.charted_procedure_id where it.deleted_at is null and cp.status not in ('completed','invoiced','cancelled') and it.treatment_plan_phase_id in (select id from treatment_plan_phases where treatment_plan_id=t.id)) and exists (select 1 from treatment_plan_items it join charted_procedures cp on cp.id=it.charted_procedure_id where cp.status in ('completed','invoiced') and it.treatment_plan_phase_id in (select id from treatment_plan_phases where treatment_plan_id=t.id));
select 'I21 accepted/scheduled proc without price', count(*) from charted_procedures where status in ('accepted','scheduled') and price is null and deleted_at is null;
select 'I22 cross-org references (invoice vs patient)', count(*) from invoices i join patients p on p.id=i.patient_id where i.organization_id<>p.organization_id;
select 'I23 org count / orgs', count(*), string_agg(name,', ') from organizations;
select 'I24 completed appt in future or arrived_at before starts-1d', count(*) from appointments where completed_at>now();
select 'I25 dup patient numbers in org', count(*) from (select organization_id,patient_number from patients group by 1,2 having count(*)>1) x;
